import{_ as a,o as r,c as e,a3 as o}from"./chunks/framework.DAMTqaDZ.js";const m=JSON.parse('{"title":"Как пользоваться","description":"","frontmatter":{"outline":[2,3]},"headers":[],"relativePath":"how-to-use.md","filePath":"how-to-use.md"}'),l={name:"how-to-use.md"};function i(s,t,d,n,h,c){return r(),e("div",null,[...t[0]||(t[0]=[o('<h1 id="как-пользоваться" tabindex="-1">Как пользоваться <a class="header-anchor" href="#как-пользоваться" aria-label="Permalink to &quot;Как пользоваться&quot;">​</a></h1><p>Коротко: кому что здесь нужно и как в систему попадают изменения. Процессы описаны по плану дизайн-системы Cloud Mobile.</p><h2 id="разработчику" tabindex="-1">Разработчику <a class="header-anchor" href="#разработчику" aria-label="Permalink to &quot;Разработчику&quot;">​</a></h2><ol><li><strong>Перед тем как писать компонент</strong> — откройте <a href="/trassir-ds-demo/android/components/">все компоненты</a> своей платформы и поищите готовый. Фильтр работает по имени, семейству и пути к файлу. Сейчас в проекте 55 самописных шторок при 9 в ките именно потому, что этого шага не было.</li><li><strong>На странице компонента</strong> — таблица параметров с типами и значениями по умолчанию, вычитанная прямо из кода, и путь к файлу с номером строки.</li><li><strong>Значения оформления</strong> — не подбирайте по макету. Цвет, отступ и радиус берутся из <code>TrassirTokens</code>, см. <a href="/trassir-ds-demo/android/start">подключение для Android</a> и <a href="/trassir-ds-demo/ios/start">для iOS</a>.</li><li><strong>Расхождения платформ</strong> — проверьте <a href="/trassir-ds-demo/conflicts">конфликты</a>, прежде чем «поправить как на другой платформе».</li></ol><h2 id="дизаинеру" tabindex="-1">Дизайнеру <a class="header-anchor" href="#дизаинеру" aria-label="Permalink to &quot;Дизайнеру&quot;">​</a></h2><ol><li><strong>Значения</strong> — страницы токенов показывают то, что реально лежит в коде, а не то, что нарисовано в макете. Расхождения видно сразу.</li><li><strong>Описания компонентов</strong> живут рядом с кодом, в <code>registry/&lt;платформа&gt;/*.yaml</code>. Если на странице написано «описание не заполнено», его пишет человек, а не генератор.</li><li><strong>Прототип</strong> — <a href="/trassir-ds-demo/prototype">экраны приложения</a> в мокапе телефона: проверить сценарий целиком, а не отдельный компонент.</li><li><strong>Ревью сборки</strong> — после релиза приложения сверяйте собранное с версией дизайн-системы и заводите замечания задачами.</li></ol><h2 id="аналитике-и-продукту" tabindex="-1">Аналитике и продукту <a class="header-anchor" href="#аналитике-и-продукту" aria-label="Permalink to &quot;Аналитике и продукту&quot;">​</a></h2><ul><li>Витрина отвечает на вопрос «что уже есть в системе» без похода к разработке.</li><li><a href="/trassir-ds-demo/prototype">Прототип</a> показывает сценарий целиком и годится для обсуждения текстов и порядка шагов.</li><li>Раздел <a href="/trassir-ds-demo/conflicts">конфликтов</a> показывает, где решение о внешнем виде ещё не принято.</li></ul><h2 id="как-вносится-изменение-оформления" tabindex="-1">Как вносится изменение оформления <a class="header-anchor" href="#как-вносится-изменение-оформления" aria-label="Permalink to &quot;Как вносится изменение оформления&quot;">​</a></h2><ol><li>Дизайнер меняет значение в Figma и выгружает токены.</li><li>Открывается pull request. Робот пишет, что изменилось, сколько компонентов затронуто, и прикладывает скриншоты до и после.</li><li>Разработка смотрит и принимает либо возвращает с замечанием.</li><li>Выходит версия: минорная при добавлении, мажорная при изменении существующего значения.</li><li>Команда обновляется, когда готова, и перепроверяет только затронутые экраны.</li></ol><p>Сейчас в стенде работают шаги 1 и 4 вручную: токены правятся в репозитории, версия ставится руками. Pull request и робота с диффом ещё нет.</p><h2 id="как-заводится-новыи-компонент" tabindex="-1">Как заводится новый компонент <a class="header-anchor" href="#как-заводится-новыи-компонент" aria-label="Permalink to &quot;Как заводится новый компонент&quot;">​</a></h2><ol><li>Проверяем реестр: нет ли уже подходящего.</li><li>Бизнес-проверка внутри дизайна: отвечает ли компонент сценарию.</li><li>Проверка регламента: цвет только из токенов, отступы по шкале, все состояния описаны.</li><li>Компонент заводится одновременно в Figma и в обеих библиотеках. Имя и назначение общие, геометрия платформенная.</li><li>Рядом кладётся описание: зачем нужен, состояния, когда не применять, чем отличается соседняя платформа.</li><li>Pull request, релиз минорной версии, уведомление разработки.</li></ol><p><strong>Правило.</strong> Компонент считается существующим, только когда он есть в обеих библиотеках и описан. Нарисованный в макете, но не заведённый в код, в реестр не попадает и в витрине не показывается.</p><h2 id="чего-стенд-пока-не-делает" tabindex="-1">Чего стенд пока не делает <a class="header-anchor" href="#чего-стенд-пока-не-делает" aria-label="Permalink to &quot;Чего стенд пока не делает&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Чего нет</th><th>Что вместо этого</th></tr></thead><tbody><tr><td>Переключения версий и сравнения</td><td>Одна версия, 0.1.0</td></tr><tr><td>Списка изменений</td><td>Ведём руками в сообщениях коммитов</td></tr><tr><td>Скриншотов компонентов и сравнения картинок</td><td>Живые образцы на вёрстке, без эталонов</td></tr><tr><td>Pull request и робота с диффом</td><td>Правки идут прямо в репозиторий</td></tr><tr><td>Ссылок на Figma и Confluence</td><td>Поля есть, значения пустые</td></tr></tbody></table><p>Это следующие шаги, они же этапы 3 и 4 плана.</p>',17)])])}const f=a(l,[["render",i]]);export{m as __pageData,f as default};
